import jetbrains.buildServer.configs.kotlin.*
import jetbrains.buildServer.configs.kotlin.buildFeatures.XmlReport
import jetbrains.buildServer.configs.kotlin.buildFeatures.perfmon
import jetbrains.buildServer.configs.kotlin.buildFeatures.xmlReport
import jetbrains.buildServer.configs.kotlin.buildSteps.script
import jetbrains.buildServer.configs.kotlin.failureConditions.BuildFailureOnMetric
import jetbrains.buildServer.configs.kotlin.failureConditions.failOnMetricChange
import jetbrains.buildServer.configs.kotlin.triggers.schedule
import jetbrains.buildServer.configs.kotlin.triggers.vcs

/*
 * TestHarness pipeline as TeamCity Kotlin DSL — the same stages as .github/workflows/ci.yml.
 *
 * STATUS: compiled and generated by CI (`mvn -f .teamcity/pom.xml teamcity-configs:generate`,
 * job "teamcity-dsl"), but NOT executed on a TeamCity server. Agent requirements (Docker,
 * browsers) are declared, not proven on a real agent pool.
 *
 * Shape:
 *   Build ──┬─ API suite ─────────────┐
 *           ├─ BDD suite ─────────────┤
 *           ├─ UI suite × 3 browsers × 2 shards
 *           ├─ Compose smoke ─────────┤
 *           ├─ Selenium Grid ─────────┼─ Quality gate (composite: green only if all blocking builds are)
 *           ├─ Gatling smoke ─────────┤
 *           ├─ Mutation (PIT) ────────┘
 *           └─ Quarantined tests (not a dependency of the gate: reported, never blocking)
 *   Allure report: runs after the suites even when they fail, collecting their results.
 */

version = "2025.07"


/** Common to every Maven build: JDK 21, Docker on the agent, surefire results imported. */
fun BuildType.mavenBasics() {
    vcs { root(DslContext.settingsRoot) }
    requirements {
        exists("env.JDK_21_0")
        exists("docker.server.version")
    }
    features {
        perfmon {}
        xmlReport {
            reportType = XmlReport.XmlReportType.SUREFIRE
            rules = "+:**/target/surefire-reports/TEST-*.xml"
        }
    }
}

/** A Maven Wrapper step (the wrapper pins Maven, so agents need only a JDK). */
fun BuildSteps.mvn(stepName: String, goals: String, args: String = "") {
    script {
        name = stepName
        scriptContent = "JAVA_HOME=%env.JDK_21_0% ./mvnw %mvn.args% $goals $args"
    }
}

val Build: BuildType = BuildType {
    id("Build")
    name = "1. Build + framework & SUT tests"
    description = "Compiles everything; unit, framework (real Chrome), SUT integration and Pact tests"
    mavenBasics()
    steps {
        mvn("Build and test (no suites)", "install",
            "-pl sut/gate-domain,sut/gate-ui,sut/gate-api,harness/harness-core,harness/harness-reporting," +
                "harness/harness-data,harness/harness-api,harness/harness-ui,harness/harness-bdd," +
                "harness/harness-insights,harness/harness-cli -am")
        script {
            name = "Consumer contract is up to date"
            scriptContent = "git diff --exit-code -- contracts/"
        }
    }
    triggers {
        vcs { branchFilter = "+:<default>\n+:pull/*" }
    }
    artifactRules = """
        sut/**/target/surefire-reports/** => reports/build.zip
        harness/**/target/surefire-reports/** => reports/build.zip
    """.trimIndent()
}

/** A suite build: snapshot-depends on Build so every suite tests the same commit. */
fun suiteBuild(buildId: String, title: String, module: String, extraArgs: String): BuildType = BuildType {
    id(buildId)
    name = title
    mavenBasics()
    dependencies { snapshot(Build) { onDependencyFailure = FailureAction.FAIL_TO_START } }
    steps {
        mvn("Build upstream modules", "install", "-DskipTests -pl $module -am")
        mvn("Run", "verify", "-pl $module -Dharness.quarantine.mode=exclude $extraArgs")
    }
    artifactRules = """
        $module/target/surefire-reports/** => reports
        target/allure-results/** => allure-results.zip
        +:$module/target/evidence/** => evidence
    """.trimIndent()
    failureConditions {
        // A suite that silently runs far fewer tests than last time is a failure too.
        failOnMetricChange {
            metric = BuildFailureOnMetric.MetricType.TEST_COUNT
            threshold = 20
            units = BuildFailureOnMetric.MetricUnit.PERCENTS
            comparison = BuildFailureOnMetric.MetricComparison.LESS
            compareTo = build { buildRule = lastSuccessful() }
        }
    }
}

val ApiSuite = suiteBuild("ApiSuite", "2. API + security suite", "suites/api-suite", "")
val BddSuite = suiteBuild("BddSuite", "3. BDD suite", "suites/bdd-suite", "")

/** The UI suite in three browsers, each split in two by a stable hash of the test keys. */
val UiBuilds: List<BuildType> = listOf("chrome", "firefox", "edge").flatMap { browser ->
    listOf(1, 2).map { shard ->
        suiteBuild("UiSuite_${browser}_$shard", "4. UI suite - $browser, shard $shard/2", "suites/ui-suite",
            "-Dharness.ui.browser=$browser -Dharness.visual.platform=$browser-ci -Dharness.shard=$shard/2")
    }
}

val ComposeSmoke: BuildType = BuildType {
    id("ComposeSmoke")
    name = "5. Docker Compose SUT + API suite (external mode)"
    mavenBasics()
    dependencies { snapshot(Build) {} }
    steps {
        script { name = "Start the SUT"; scriptContent = "docker compose up -d --build --wait" }
        mvn("Build upstream modules", "install", "-DskipTests -pl suites/api-suite -am")
        mvn("API suite against the container", "verify", "-pl suites/api-suite -Dharness.env=docker")
        script {
            name = "Stop"
            executionMode = BuildStep.ExecutionMode.ALWAYS
            scriptContent = "docker compose down -v"
        }
    }
}

val Grid: BuildType = BuildType {
    id("Grid")
    name = "6. Selenium Grid — UI suite on Chrome, Firefox, Edge nodes"
    mavenBasics()
    dependencies { snapshot(Build) {} }
    steps {
        script {
            name = "Start SUT + Grid"
            scriptContent = "docker compose -f docker-compose.yml -f docker-compose.grid.yml up -d --build --wait"
        }
        mvn("Build upstream modules", "install", "-DskipTests -pl suites/ui-suite -am")
        mvn("UI suite on the Grid", "verify",
            "-pl suites/ui-suite -Dharness.env=docker -Dharness.ui.grid-url=http://localhost:4444 " +
                "-Dharness.sut.browser-base-url=http://gate:8080 -DexcludedGroups=visual")
        script {
            name = "Stop"
            executionMode = BuildStep.ExecutionMode.ALWAYS
            scriptContent = "docker compose -f docker-compose.yml -f docker-compose.grid.yml down -v"
        }
    }
}

val Perf: BuildType = BuildType {
    id("Perf")
    name = "7. Gatling performance smoke (p95/p99/error gates)"
    mavenBasics()
    dependencies { snapshot(Build) {} }
    steps {
        mvn("Build upstream modules", "install", "-DskipTests -DskipPerf -pl suites/perf-suite -am")
        mvn("Booking flow under load", "verify", "-pl suites/perf-suite")
    }
    artifactRules = "suites/perf-suite/target/gatling/** => gatling.zip"
}

val Mutation: BuildType = BuildType {
    id("Mutation")
    name = "8. Mutation testing (PIT) — domain rules, 95 % gate"
    mavenBasics()
    dependencies { snapshot(Build) {} }
    steps { mvn("PIT", "verify", "-Pmutation -pl sut/gate-domain") }
    artifactRules = "sut/gate-domain/target/pit-reports/** => pit-report.zip"
}

val Quarantined: BuildType = BuildType {
    id("Quarantined")
    name = "Quarantined tests (non-blocking)"
    description = "Runs only what quarantine.json lists; not a dependency of the quality gate"
    mavenBasics()
    dependencies { snapshot(Build) {} }
    steps {
        mvn("Build upstream modules", "install", "-DskipTests -pl suites/flaky-demo -am")
        mvn("Quarantined tests", "verify", "-pl suites/flaky-demo -DskipFlakyDemo=false -Dharness.quarantine.mode=only")
    }
    failureConditions {
        // Quarantine is visible, never blocking: test failures do not fail this build.
        testFailure = false
        nonZeroExitCode = false
    }
}

fun allureReport(suites: List<BuildType>): BuildType = BuildType {
    id("AllureReport")
    name = "Allure report"
    mavenBasics()
    dependencies {
        suites.forEach { suite ->
            dependency(suite) {
                snapshot { onDependencyFailure = FailureAction.IGNORE; onDependencyCancel = FailureAction.IGNORE }
                artifacts {
                    artifactRules = "allure-results.zip!** => target/allure-results"
                    cleanDestination = false
                }
            }
        }
    }
    steps { mvn("Generate report", "verify", "-N -Preport") }
    artifactRules = "target/allure-report/** => allure-report.zip"
}

/** The one check to require on pull requests: a composite build over every blocking build. */
fun qualityGate(blocking: List<BuildType>): BuildType = BuildType {
    id("QualityGate")
    name = "Quality gate"
    type = BuildTypeSettings.Type.COMPOSITE
    vcs { root(DslContext.settingsRoot) }
    dependencies { blocking.forEach { snapshot(it) { onDependencyFailure = FailureAction.FAIL_TO_START } } }
    triggers {
        vcs { branchFilter = "+:<default>\n+:pull/*" }
        schedule {
            schedulingPolicy = daily { hour = 2 }
            branchFilter = "+:<default>"
            triggerBuild = always()
        }
    }
}

// Declared last: the top-level vals above (suites, UI shards) must be initialised first.
project {
    description = "Test automation framework with a seeded-defect SUT (github.com/RaktimChandra/TestHarness)"

    params {
        param("env.HARNESS_ENV", "ci")
        param("mvn.args", "-B -ntp --fail-at-end")
        password("env.GATE_SEED_PASSWORD", "credentialsJSON:gate-seed-password",
            label = "Seed users' password", display = ParameterDisplay.HIDDEN)
    }

    buildType(Build)
    buildType(ApiSuite)
    buildType(BddSuite)
    UiBuilds.forEach { buildType(it) }
    buildType(ComposeSmoke)
    buildType(Grid)
    buildType(Perf)
    buildType(Mutation)
    buildType(Quarantined)
    buildType(allureReport(listOf(ApiSuite, BddSuite) + UiBuilds))
    buildType(qualityGate(listOf(Build, ApiSuite, BddSuite, ComposeSmoke, Grid, Perf, Mutation) + UiBuilds))

    buildTypesOrder = listOf(Build, ApiSuite, BddSuite) + UiBuilds +
        listOf(ComposeSmoke, Grid, Perf, Mutation, Quarantined)
}
